    public record LatePctForm(@NotBlank @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = DATE) String from) implements Dated {

        BigDecimal latePctValue() {
